using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int CeilingPoints = 10;

    public int For(LoyaltyTier tier, int subtotalCents)
    {
        var points = Math.Min(BasePoints(tier) + BonusPoints(subtotalCents), CeilingPoints);
        var discountCents = (int)((long)subtotalCents * points / 100);
        return subtotalCents - discountCents;
    }

    private static int BasePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
    };

    private static int BonusPoints(int subtotalCents) => subtotalCents switch
    {
        < 5000 => 0,
        < 20000 => 1,
        _ => 3,
    };
}
E
